properties.query:
let supply_events = SecurityEvent | where EventID == 4688 and ProcessName has_any ("npm", "pip", "gradle", "maven") and ProcessCommandLine has_any ("-g", "install", "--force") | summarize supply_time=min(TimeGenerated) by Computer;
let build_events = SecurityEvent | where EventID == 4688 and ProcessName has_any ("msbuild.exe", "docker", "kubectl") | summarize build_time=min(TimeGenerated) by Computer;
let prod_events = SecurityEvent | where EventID == 4624 and Computer startswith "prod-" | summarize prod_time=min(TimeGenerated) by Computer;
supply_events | join kind=inner build_events on Computer | where build_time - supply_time between (0min .. 120min)
